PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    short_name TEXT,
    active BOOLEAN DEFAULT 1
);
CREATE TABLE matches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    match_key TEXT NOT NULL UNIQUE,
    year INTEGER NOT NULL,
    round TEXT NOT NULL,          -- e.g. 'Rd 1', 'Prelim', 'GF'
    game_num INTEGER NOT NULL,    -- game number within the round
    home_team_id INTEGER NOT NULL,
    away_team_id INTEGER NOT NULL,
    home_score INTEGER,
    away_score INTEGER,
    home_elo_before REAL,
    away_elo_before REAL,
    home_elo_after REAL,
    away_elo_after REAL,
    completed BOOLEAN DEFAULT 0, odds_tip TEXT, user_tip TEXT, venue_name TEXT, home_odds REAL, away_odds REAL, home_odds_open REAL, away_odds_open REAL, home_odds_close REAL, away_odds_close REAL, primary_home_venue TEXT,
    FOREIGN KEY (home_team_id) REFERENCES teams(id),
    FOREIGN KEY (away_team_id) REFERENCES teams(id)
);
CREATE TABLE elo_ratings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    team_id INTEGER NOT NULL,
    rating REAL NOT NULL,
    year INTEGER NOT NULL,
    round TEXT NOT NULL,
    rank INTEGER,
    FOREIGN KEY (team_id) REFERENCES teams(id)
);
CREATE TABLE parameters (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    value REAL NOT NULL,
    description TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_matches_order 
ON matches(year, round, game_num, id);
CREATE INDEX idx_elo_ratings_team_round 
ON elo_ratings(team_id, year, round);
